//! Offline additive stage changes and actual callback completion tails.
use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,collections::{BTreeMap,BTreeSet},path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/msm-c7a180";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn sha(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn mean(v:&[f64])->f64{assert!(!v.is_empty());v.iter().sum::<f64>()/v.len()as f64}
fn main(){let raw=format!("{R}/remote-results/output/msm-c7a180");let rows=read(format!("{raw}/rows.json"));let review=read(format!("{raw}/review.json"));let pins=read(format!("{R}/transport/pins.json"));let mut changes=vec![];let mut geometry=vec![];
 for mode in ["zopro","sorted","windowed"]{let by=|w,b|rows.as_array().unwrap().iter().find(|r|r["job"]["mode"]==mode&&r["job"]["arm"]=="ON"&&r["job"]["workers"]==w&&r["job"]["block"]==b).unwrap();for key in by(32,0)["phase_mean_ms"].as_object().unwrap().keys(){let mut a=vec![];let mut b=vec![];for block in 0..9{a.push(by(32,block)["phase_mean_ms"][key].as_f64().unwrap());b.push(by(96,block)["phase_mean_ms"][key].as_f64().unwrap());}let ds=b.iter().zip(&a).map(|(b,a)|b-a).collect::<Vec<_>>();changes.push(json!({"mode":mode,"phase":key,"mean32_ms":mean(&a),"mean96_ms":mean(&b),"delta96_minus32_ms":mean(&ds),"decreasing_blocks":ds.iter().filter(|&&v|v<0.).count(),"block_deltas_ms":ds}));}
 for w in [32,96]{let mut gg=BTreeSet::new();for b in 0..9{for g in by(w,b)["work_geometries"].as_array().unwrap(){gg.insert(serde_json::to_string(g).unwrap());}}geometry.push(json!({"mode":mode,"workers":w,"distinct_geometries":gg.iter().map(|s|serde_json::from_str::<Value>(s).unwrap()).collect::<Vec<_>>()}));}}
 let mut tails=vec![];for (label,root,counts) in [("c7a",raw.clone(),[32,96]),("local","/home/ubuntu/src/zopro-perf-work/msm-local180".into(),[16,32])]{for w in counts{let mut blocks=vec![];let mut all=vec![];let mut last_count=0;for b in 0..9{let path=format!("{root}/checks/main-w{w}-zopro-ON-b{b:02}.json");if label=="c7a"{assert_eq!(sha(&path),pins[&path].as_str().unwrap());}let p=read(&path);let pp=p["phases"].as_array().unwrap();assert_eq!(pp.len(),54);let mut ts=vec![];let mut last=0;for phase in pp.iter().skip(3){assert_eq!(phase["valid"],true);let rows=phase["rows"].as_array().unwrap();assert_eq!(rows[4]["phase"],"A");assert_eq!(rows[5]["phase"],"KH");assert_eq!(rows[6]["phase"],"G2");let end=|i:usize|rows[i]["end_ns"].as_u64().unwrap();let g1=end(4).max(end(5));if end(6)>=g1{last+=1;}ts.push(end(6).saturating_sub(g1)as f64/1e6);}assert_eq!(ts.len(),51);blocks.push(json!({"block":b,"mean_g2_callback_only_tail_ms":mean(&ts),"g2_last_requests":last}));all.extend(ts);last_count+=last;}tails.push(json!({"host":label,"workers":w,"requests":all.len(),"mean_g2_callback_only_tail_ms":mean(&all),"g2_last_requests":last_count,"blocks":blocks,"not_exclusive_arithmetic_or_removable_time":true}));}}
 let stages=["solve","prepare","fft","queries","output","unassigned_within_observer","request_outside_observer"];let find=|phase:&str|changes.iter().find(|v|v["mode"]=="zopro"&&v["phase"]==phase).unwrap()["delta96_minus32_ms"].as_f64().unwrap();let delta=stages.iter().map(|p|find(p)).sum::<f64>();let ctx=|w|review["contexts"].as_array().unwrap().iter().find(|v|v["mode"]=="zopro"&&v["arm"]=="ON"&&v["workers"]==w).unwrap()["pooled_mean_ms"].as_f64().unwrap();assert!((ctx(96)-ctx(32)-delta).abs()<1e-9);let pre=find("solve")+find("prepare")+find("fft");
 let mut guard_recheck=vec![];for g in review["backing_guards"].as_array().unwrap(){let source=review["gates"].as_array().unwrap().iter().find(|s|s["mode"]==g["mode"]&&s["workers"]==g["workers"]&&s["ratio"]==g["ratio"]).unwrap();let backing=g["backing"].as_u64().unwrap()as usize;let mut v=(backing..9).step_by(3).map(|b|source["block_ratios"][b].as_f64().unwrap()).collect::<Vec<_>>();v.sort_by(f64::total_cmp);assert_eq!(v[1],g["median"].as_f64().unwrap());assert_eq!((0.95..=1.05).contains(&v[1]),g["passed"].as_bool().unwrap());guard_recheck.push(g.clone());}assert_eq!(guard_recheck.len(),48);
 let out=json!({"stage_changes":changes,"geometry":geometry,"zopro_completion_tails":tails,"zopro_additive_delta_ms":delta,"zopro_prequery_increase_ms":pre,"zopro_arithmetic_counterfactual_96_with_32_prequery_ms":ctx(96)-pre,"counterfactual_is_not_a_measured_optimization":true,"backing_guards_recomputed":48,"calibration_passed":review["gates"].as_array().unwrap().iter().filter(|g|g["passed"]==true).count(),"backing_passed":guard_recheck.iter().filter(|g|g["passed"]==true).count(),"fresh_sorted_trace_not_qualified_as_retained96_reference":true});let dest=format!("{R}/stage-analysis.json");assert!(!Path::new(&dest).exists());fs::write(dest,serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Additive decomposition and real callback tails checked;48 backing guards reproduced; no SDK or verifier replay");}
